// === Миграция знаний Git → Supabase (исправленная) ===

ХостGit = СтрЗаменить(Объект.АдресGitAPI, "https://", "");
Репозиторий = Объект.РепозиторийGit;
Ветка = Объект.ВеткаGit;
ТокенGit = Объект.ТокенGit;
КаталогЗнаний = Объект.КаталогБазыЗнанийGit;

ХостСупа = "bsitoitguoagjteajedw.supabase.co";
ТокенСупа = "sb_publishable_t8H5y5pWJ56Se9OEl3q36g_KOnnf4YR";

SSL = Новый ЗащищенноеСоединениеOpenSSL;
Гит = Новый HTTPСоединение(ХостGit, 443, , , , 120, SSL);
Супа = Новый HTTPСоединение(ХостСупа, 443, , , , 120, SSL);

ЗагГит = Новый Соответствие;
ЗагГит.Вставить("Authorization", "Bearer " + ТокенGit);
ЗагГит.Вставить("Accept", "application/vnd.github.v3+json");

ЗагГитRaw = Новый Соответствие;
ЗагГитRaw.Вставить("Authorization", "Bearer " + ТокенGit);
ЗагГитRaw.Вставить("Accept", "application/vnd.github.v3.raw");

ЗагСупа = Новый Соответствие;
ЗагСупа.Вставить("apikey", ТокенСупа);
ЗагСупа.Вставить("Authorization", "Bearer " + ТокенСупа);
ЗагСупа.Вставить("Content-Type", "application/json");
ЗагСупа.Вставить("Accept", "application/json");

// Функция URL-кодирования пути
КодированПуть = "";
ПутьДляКода = "";

Результат = "=== Миграция Git в Supabase ===" + Символы.ПС;
Успех = 0;
Ошибок = 0;
ДеревоПолучено = Ложь;
Файлы = Новый Массив;

// --- Шаг 1: Дерево файлов ---
Попытка
    ПутьДерева = "/repos/" + Репозиторий + "/git/trees/" + Ветка + ":" + КаталогЗнаний + "?recursive=1";
    ЗапросДерева = Новый HTTPЗапрос(ПутьДерева, ЗагГит);
    ОтветДерева = Гит.Получить(ЗапросДерева);
    Если ОтветДерева.КодСостояния = 200 Тогда
        Чт = Новый ЧтениеJSON;
        Чт.УстановитьСтроку(ОтветДерева.ПолучитьТелоКакСтроку());
        Дерево = ПрочитатьJSON(Чт, Ложь);
        Чт.Закрыть();
        Для Каждого Эл Из Дерево.tree Цикл
            Если Эл.type = "blob" И НРег(Прав(Эл.path, 5)) = ".json" Тогда
                Файлы.Добавить(Эл.path);
            КонецЕсли;
        КонецЦикла;
        ДеревоПолучено = Истина;
        Результат = Результат + "Найдено JSON: " + Строка(Файлы.Количество()) + Символы.ПС;
    Иначе
        Результат = Результат + "ОШИБКА дерева: HTTP " + Строка(ОтветДерева.КодСостояния) + Символы.ПС;
    КонецЕсли;
Исключение
    Результат = Результат + "ОШИБКА дерева: " + ОписаниеОшибки() + Символы.ПС;
КонецПопытки;

// --- Шаг 2: Миграция ---
Если ДеревоПолучено И Файлы.Количество() > 0 Тогда
    Всего = Файлы.Количество();
    Результат = Результат + "Начинаем миграцию " + Строка(Всего) + " файлов..." + Символы.ПС;

    Для Инд = 0 По Всего - 1 Цикл
        ПутьФайла = Файлы[Инд];

        // URL-кодируем путь (пробелы и спецсимволы)
        КодированПуть = "";
        ПутьДляКода = ПутьФайла;
        Для Поз = 1 По СтрДлина(ПутьДляКода) Цикл
            Симв = Сред(ПутьДляКода, Поз, 1);
            Код = КодСимвола(Симв);
            Если (Код >= 48 И Код <= 57)
                ИЛИ (Код >= 65 И Код <= 90)
                ИЛИ (Код >= 97 И Код <= 122)
                ИЛИ Симв = "/" ИЛИ Симв = "." ИЛИ Симв = "_" ИЛИ Симв = "-" Тогда
                КодированПуть = КодированПуть + Симв;
            Иначе
                КодированПуть = КодированПуть + "%" + ВРег(Прав("0" + ПреобразоватьВHex(Код), 2));
            КонецЕсли;
        КонецЦикла;

        // Скачиваем файл
        Загружен = Ложь;
        Обр = Неопределено;
        Попытка
            ПутьКонт = "/repos/" + Репозиторий + "/contents/" + КодированПуть;
            ЗапФайла = Новый HTTPЗапрос(ПутьКонт, ЗагГитRaw);
            ОтвФайла = Гит.Получить(ЗапФайла);
            Если ОтвФайла.КодСостояния = 200 Тогда
                Ч2 = Новый ЧтениеJSON;
                Ч2.УстановитьСтроку(ОтвФайла.ПолучитьТелоКакСтроку());
                Обр = ПрочитатьJSON(Ч2, Ложь);
                Ч2.Закрыть();
                Загружен = Истина;
            Иначе
                Ошибок = Ошибок + 1;
                Если Ошибок <= 3 Тогда
                    Результат = Результат + "HTTP " + Строка(ОтвФайла.КодСостояния) + ": " + ПутьФайла + Символы.ПС;
                КонецЕсли;
            КонецЕсли;
        Исключение
            Ошибок = Ошибок + 1;
            Если Ошибок <= 3 Тогда
                Результат = Результат + "ОШИБКА загрузки: " + ОписаниеОшибки() + Символы.ПС;
            КонецЕсли;
        КонецПопытки;

        // Вставляем в Supabase
        Если Загружен И Обр <> Неопределено Тогда
            Попытка
                ВремяМетка = "";
                Если Обр.Свойство("timestamp") Тогда
                    ВремяМетка = Обр.timestamp;
                КонецЕсли;
                Если НЕ ЗначениеЗаполнено(ВремяМетка) Тогда
                    ВремяМетка = Формат(ТекущаяДата(), "ДФ=yyyy-MM-ddTHH:mm:ssZ");
                КонецЕсли;

                ЗапJSON = Новый ЗаписьJSON;
                ЗапJSON.УстановитьСтроку();
                ЗапJSON.ЗаписатьНачалоМассива();
                ЗапJSON.ЗаписатьНачалоОбъекта();
                ЗапJSON.ЗаписатьИмяСвойства("fingerprint");
                ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("fingerprint"), Строка(Обр.fingerprint), ""));
                ЗапJSON.ЗаписатьИмяСвойства("task");
                ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("task"), Строка(Обр.task), ""));
                ЗапJSON.ЗаписатьИмяСвойства("code");
                ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("code"), Строка(Обр.code), ""));
                ЗапJSON.ЗаписатьИмяСвойства("lang");
                ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("lang"), Строка(Обр.lang), ""));
                ЗапJSON.ЗаписатьИмяСвойства("result");
                ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("result"), Строка(Обр.result), ""));
                ЗапJSON.ЗаписатьИмяСвойства("success");
                ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("success"), Обр.success, Ложь));
                ЗапJSON.ЗаписатьИмяСвойства("type");
                ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("type"), Строка(Обр.type), ""));
                ЗапJSON.ЗаписатьИмяСвойства("timestamp");
                ЗапJSON.ЗаписатьЗначение(ВремяМетка);
                ЗапJSON.ЗаписатьКонецОбъекта();
                ЗапJSON.ЗаписатьКонецМассива();
                ТелоВст = ЗапJSON.Закрыть();

                ЗапВст = Новый HTTPЗапрос("/rest/v1/knowledge", ЗагСупа);
                ЗапВст.УстановитьТелоИзСтроки(ТелоВст, КодировкаТекста.UTF8, ИспользованиеByteOrderMark.НеИспользовать);
                ОтвВст = Супа.ОтправитьДляОбработки(ЗапВст);

                Если ОтвВст.КодСостояния >= 200 И ОтвВст.КодСостояния < 300 Тогда
                    Успех = Успех + 1;
                Иначе
                    Ошибок = Ошибок + 1;
                    Если Ошибок <= 3 Тогда
                        Результат = Результат + "INSERT " + Строка(ОтвВст.КодСостояния) + ": " + Лев(ОтвВст.ПолучитьТелоКакСтроку(), 200) + Символы.ПС;
                    КонецЕсли;
                КонецЕсли;
            Исключение
                Ошибок = Ошибок + 1;
                Если Ошибок <= 3 Тогда
                    Результат = Результат + "ОШИБКА INSERT: " + ОписаниеОшибки() + Символы.ПС;
                КонецЕсли;
            КонецПопытки;
        КонецЕсли;

        // Прогресс каждые 50
        Если (Инд + 1) % 50 = 0 Тогда
            Результат = Результат + "Обработано: " + Строка(Инд + 1) + "/" + Строка(Всего) + Символы.ПС;
        КонецЕсли;
    КонецЦикла;

    Результат = Результат + Символы.ПС;
КонецЕсли;

Результат = Результат
    + "=== Итог ===" + Символы.ПС
    + "Успешно: " + Строка(Успех) + Символы.ПС
    + "Ошибок: " + Строка(Ошибок) + Символы.ПС;
